INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47411, 'Isaiah 32:3', 'Isaiah', 32, 3, 'نو بیا به د هغوی سترګې د حقیقت د لیدلو دپاره بندې نه وي او غوږونه به یې د اورېدلو دپاره خلاص وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_3.mp3', '', 1761754199, 1761754199),
(47412, 'Isaiah 32:4', 'Isaiah', 32, 4, 'هغوی به نور نه بې حوصلې کیږي، بلکې په هوښیارۍ سره به عمل کوي. د چا چې ژبه بندیږي هغوی به د خلکو سره په روانه ژبه خبرې وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_4.mp3', '', 1761754199, 1761754199),
(47413, 'Isaiah 32:5', 'Isaiah', 32, 5, 'نور به هېڅوک بې عقله سړي ته شریف او رذیل سړي ته نېک ونه وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_5.mp3', '', 1761754199, 1761754199),
(47414, 'Isaiah 32:6', 'Isaiah', 32, 6, 'بې عقله سړی بې عقلې خبرې کوي او د بدو کارونو په اړه فکر کوي. هغه غواړي چې بد کارونه او د څښتن په خلاف غلطې ویناوې وکړي. له وږو خلکو سره مرسته نه کوي او تږو خلکو ته اوبه نه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_6.mp3', '', 1761754199, 1761754199),
(47415, 'Isaiah 32:7', 'Isaiah', 32, 7, 'رذیل سړی بد سړی وي او بد کارونه کوي. هغه د دروغو په ویلو سره د غریبانو د تباه کولو دپاره دسیسې جوړوي او د دې مخه نیسي چې هغوی دې خپل حقونه تر لاسه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_7.mp3', '', 1761754199, 1761754199),
(47416, 'Isaiah 32:8', 'Isaiah', 32, 8, 'خو شریف خلک د نېک کار نقشه جوړوي او په نېک کار باندې ټینګ ولاړ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_8.mp3', '', 1761754199, 1761754199),
(47417, 'Isaiah 32:9', 'Isaiah', 32, 9, 'ای بې پروا ښځو، چې هوسا ژوند لرئ، زما خبرو ته غوږ ونیسئ. ای مېرمنو، چې په ځان باندې تکیه کوئ زما وینا ته پام وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_9.mp3', '', 1761754199, 1761754199),
(47418, 'Isaiah 32:10', 'Isaiah', 32, 10, 'اوس تاسو د خپل ژوند څخه راضي یئ، خو یو کال او څو ورځې وروسته به تاسو په لړزېدلو شئ، ځکه د انګورو او د نورو مېوو حاصلات به نه وي چې هغه راټول کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_10.mp3', '', 1761754199, 1761754199),
(47419, 'Isaiah 32:11', 'Isaiah', 32, 11, 'ای ښځو، تاسو چې ارام او بې غمه ژوند لرئ، اوس له وېرې په لړزېدلو شئ! خپل کالي وباسئ، بربنډې شئ او د ویر کالي واغوندئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_11.mp3', '', 1761754199, 1761754199),
(47420, 'Isaiah 32:12', 'Isaiah', 32, 12, 'له غمه خپلې سینې ووهئ، ځکه چې حاصلخېزه پټي او د انګورو تاکونه مو تباه شوي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_12.mp3', '', 1761754199, 1761754199),
(47421, 'Isaiah 32:13', 'Isaiah', 32, 13, 'او د اغزیو او د کرکڼو بوټي زما د قوم په ځمکه کې راشنه شوي دي. هو، په دې خاطر هم غم وکړئ چې د هغو د کورونو او د ښار خوشحالي او خندا به پای ته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_13.mp3', '', 1761754199, 1761754199),
(47422, 'Isaiah 32:14', 'Isaiah', 32, 14, 'حتی پاچا به هم شاهي ماڼۍ پرېږدي او له ګڼه ګوڼې ډک پایتخت به له خلکو څخه بیخي خالي شي. هغه جنګي کلا او د هغه برجونه چې د هغو په وسیله به څارنه کېدله، هغه به وران او د تل دپاره به د حیواناتو استوګن ځای شي. ځنګلي خره به په کې هسې ګرځي او راګرځي او پسونه به په کې څریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_14.mp3', '', 1761754199, 1761754199),
(47423, 'Isaiah 32:15', 'Isaiah', 32, 15, 'تر هغه وخته به حالات همداسې وي، ترڅو چې د اسمان څخه په مونږ باندې د خدای روح نازل شي. دښته به په حاصلخیزه پټي بدله شي او دا پټی به ډېر حاصلخېزه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_15.mp3', '', 1761754199, 1761754199),
(47424, 'Isaiah 32:16', 'Isaiah', 32, 16, 'نو بیا به عدالت په دښته کې پیاده شي او انصاف به په حاصلخیزه پټي کې عملي شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_16.mp3', '', 1761754199, 1761754199),
(47425, 'Isaiah 32:17', 'Isaiah', 32, 17, 'د انصاف نتیجه به تلپاتې سوله او امن وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_17.mp3', '', 1761754199, 1761754199),
(47426, 'Isaiah 32:18', 'Isaiah', 32, 18, 'زما قوم به په امن ځایونو کې اوسیږي او کورونه به یې خوندي او ارام وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_18.mp3', '', 1761754199, 1761754199),
(47427, 'Isaiah 32:19', 'Isaiah', 32, 19, 'حتی که ږلۍ ځنګلونه ویجاړ هم کړي او ښارونه د خاورو سره خاورې هم شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_19.mp3', '', 1761754199, 1761754199),
(47428, 'Isaiah 32:20', 'Isaiah', 32, 20, 'بختور یئ تاسو چې د کروندو دپاره پرېمانه اوبه لرئ او د خرو او غویانو دپاره هر چېرته د څرېدلو ځایونه لرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_20.mp3', '', 1761754199, 1761754199),
(47429, 'Job 4:1', 'Job', 4, 1, 'بيا تيمانى اليفز په جواب کښې ووئيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_1.mp3', '', 1761754199, 1761754199),
(47430, 'Job 4:2', 'Job', 4, 2, '”کۀ څوک تا ته يوه خبره وکړى نو تۀ به خفه کېږې څۀ؟ خو د خبرو نه څوک ځان منع کولے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_2.mp3', '', 1761754199, 1761754199),
(47431, 'Job 4:3', 'Job', 4, 3, 'ګوره، تا ډېرو خلقو ته ښودنه کړې ده، تا کمزورى لاسونه تکړه کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_3.mp3', '', 1761754199, 1761754199),
(47432, 'Job 4:4', 'Job', 4, 4, 'ستا ډاډګيرنې خلق په خپلو پښو ودرولى دى. کوم خلق چې په غورزېدو وُو هغوئ يې نېغ کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_4.mp3', '', 1761754199, 1761754199),
(47433, 'Job 4:5', 'Job', 4, 5, 'خو اوس مصيبت په تا باندې راغلے دے او تۀ وارخطا يې، چې دا تا له درنزدې شى نو تۀ پرېشانه شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_5.mp3', '', 1761754199, 1761754199),
(47434, 'Job 4:6', 'Job', 4, 6, 'ستا اعتماد د خُدائ پاک يره نۀ ده څۀ، او ستا نېک عمل تا له اُميد نۀ درکوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_6.mp3', '', 1761754199, 1761754199),
(47435, 'Job 4:7', 'Job', 4, 7, 'اوس دا سوچ وکړه، داسې څوک شته چې بې‌ګناه وى او تباه شى؟ او داسې څوک صادق شته چې تباه شوے وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_7.mp3', '', 1761754199, 1761754199),
(47436, 'Job 4:8', 'Job', 4, 8, 'چې څومره ما ته پته ده، چې چا دا بې‌اِنصافى کړې ده چې چا مصيبت کَرلے دے، نو هغۀ مصيبت رېبلے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_8.mp3', '', 1761754199, 1761754199),
(47437, 'Job 4:9', 'Job', 4, 9, 'د خُدائ پاک د ساه په ذريعه هغوئ سزا موندلې ده، او د هغۀ د غصې د زور په وجه هغوئ تباه شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_9.mp3', '', 1761754199, 1761754199),
(47438, 'Job 4:10', 'Job', 4, 10, 'بدعمله د ازمرى په شان غړمبيږى، خو خُدائ پاک هغوئ غلى کوى او غاښونه يې ماتوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_10.mp3', '', 1761754199, 1761754199),
(47439, 'Job 4:11', 'Job', 4, 11, 'لکه چې تکړه ازمرے د ښکار د کمى په وجه هلاکيږى، او د دې واړۀ بچى خوارۀ وارۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_11.mp3', '', 1761754199, 1761754199),
(47440, 'Job 4:12', 'Job', 4, 12, 'اوس ما ته پټ پټ يو خبر راغلو، او زما غوږُونو ته د دې غلے شان آواز راغلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_12.mp3', '', 1761754199, 1761754199),
(47441, 'Job 4:13', 'Job', 4, 13, 'په نيمه شپه ما يو يروونکے خوب وليدو، دا په هغه وخت وو چې خلق په دروند خوب اودۀ وُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_13.mp3', '', 1761754199, 1761754199),
(47442, 'Job 4:14', 'Job', 4, 14, 'يره او لړزان په ما باندې راغلل، چې دې زما ټول بدن وخوځولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_14.mp3', '', 1761754199, 1761754199),
(47443, 'Job 4:15', 'Job', 4, 15, 'يو روح زما په وړاندې تېر شو او زما په بدن وېښتۀ نېغ ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_15.mp3', '', 1761754199, 1761754199),
(47444, 'Job 4:16', 'Job', 4, 16, 'هغه روح ولاړ وو، خو ما ته پته نشته چې دا څۀ وُو. زما د سترګو په وړاندې يو شکل وو، هر څۀ خاموش وُو، بيا ما يو آواز واورېدو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_16.mp3', '', 1761754199, 1761754199),
(47445, 'Job 4:17', 'Job', 4, 17, 'ولې انسان کولے شى چې د خُدائ پاک په وړاندې صادق شى څۀ؟ ولې انسان د خالِق نه زيات پاک کېدے شى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_17.mp3', '', 1761754199, 1761754199),
(47446, 'Job 4:18', 'Job', 4, 18, 'تر دې پورې چې هغه په خپلو خِدمتګارانو باندې هم اعتماد نۀ کوى، او هغه د خپلو فرښتو کار ته هم غلط وائى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_18.mp3', '', 1761754199, 1761754199),
(47447, 'Job 4:19', 'Job', 4, 19, 'نو هغه به په انسان باندې څومره کم اعتماد وکړى څوک چې د خاورې نه جوړ وى. نو څوک چې د خاورى نه جوړ وى هغه به د پتنګ په شان په آسانۍ ذرې ذرې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_19.mp3', '', 1761754199, 1761754199),
(47448, 'Job 4:20', 'Job', 4, 20, 'سحر روغ وى او ماښام مړ شى. او څوک هم پرې خبر نۀ شى او د تل دپاره تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_20.mp3', '', 1761754199, 1761754199),
(47449, 'Job 4:21', 'Job', 4, 21, 'د هغوئ نه خپل ټول مال اخستے شوے دے، هغوئ په جاهليت مړۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job4_verse_21.mp3', '', 1761754199, 1761754199),
(47450, 'Deuteronomy 9:1', 'Deuteronomy', 9, 1, 'ای د اسراییلو خلکو واورئ! تاسو به زر د اردن د سیند څخه تېر شئ چې هغې خاورې ته ورننوځئ او هغه قومونه وشړئ چې ستاسو څخه لوی او قوي دي. د هغوی ښارونه لوی لوی دي او داسې دېوالونه لري چې اسمان ته رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_1.mp3', '', 1761754199, 1761754199),
(47451, 'Deuteronomy 9:2', 'Deuteronomy', 9, 2, 'د دې قومونو څخه ځینې یې د عناقیانو اولاده ده. تاسو پوهېږئ چې هغوی څومره لوړ قدي او قوي خلک دي او تاسو اورېدلي دي چې هېڅوک هغوی ته په جنګ کې ماتې نه شي ورکولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_2.mp3', '', 1761754199, 1761754199),
(47452, 'Deuteronomy 9:3', 'Deuteronomy', 9, 3, 'خو اوس به تاسو په خپله ووینئ چې ستاسو څښتن خدای به د تباه کوونکي اور په شان ستاسو په مخکې روان شي. کله چې تاسو په هغوی باندې حمله وکړئ هغه به هغوی ته ماتې ورکړي، نو د څښتن د وعدې سره سم به تاسو هغوی وشړئ او زر به یې له منځه یوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_3.mp3', '', 1761754199, 1761754199),
(47453, 'Deuteronomy 9:7', 'Deuteronomy', 9, 7, 'دا خبره هېڅکله هېره نه کړئ چې تاسو خپل څښتن خدای په دښته کې څنګه په قهر کړ. د هغې ورځې څخه نیولې چې تاسو د مصر څخه لاړئ تر هغې ورځې پورې چې دلته راورسېدلئ، د هغه په وړاندې مو سرکښي کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_7.mp3', '', 1761754199, 1761754199),
(47454, 'Deuteronomy 9:8', 'Deuteronomy', 9, 8, 'تاسو حتی د سینا د غره سره هم څښتن په قهر کړ. هغه مو دومره په قهر کړ چې غوښتل یې تاسو تباه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_8.mp3', '', 1761754199, 1761754199),
(47455, 'Deuteronomy 9:9', 'Deuteronomy', 9, 9, 'زه غره ته وختلم چې د تیږو لوحې راواخلم چې څښتن ورباندې هغه لوظ لیکلی ؤ چې ستاسو سره یې کړی ؤ. هلته څلوېښت شپې او ورځې پاتې شوم او نه مې څه وخوړل او نه مې څه وڅښل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_9.mp3', '', 1761754199, 1761754199),
(47456, 'Deuteronomy 9:10', 'Deuteronomy', 9, 10, 'بیا څښتن ماته د تیږو دوه لوحې راکړې چې په خپل لاس یې هغه ټولې خبرې ورباندې لیکلې وې چې ستاسو سره یې د اور د منځ څخه په هغه ورځ کړې وې چې د غره په څنګ کې راټول شوي وئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_10.mp3', '', 1761754199, 1761754199),
(47457, 'Deuteronomy 9:11', 'Deuteronomy', 9, 11, 'هو، د هغو څلوېښتو شپو او ورځو څخه وروسته څښتن ماته د تیږو دوه لوحې راکړې چې هغه حکمونه یې ورباندې لیکلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_11.mp3', '', 1761754199, 1761754199),
(47458, 'Deuteronomy 9:12', 'Deuteronomy', 9, 12, 'بیا څښتن ماته وویل: ‹پاڅېږه، همدا اوس د غره څخه ښکته شه، ځکه چې ستا قوم چې د مصر څخه دې راوویست، فاسد شوی دی او بد کار یې کړی دی. هغوی لا پخوا زما د امرونو څخه سرغړونه کړې ده او د ځانونو دپاره یې یو فلزي بت جوړ کړی دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_12.mp3', '', 1761754199, 1761754199),
(47459, 'Deuteronomy 9:13', 'Deuteronomy', 9, 13, 'څښتن ماته دا هم وویل: ‹ما دا خلک لیدلي دي چې هغوی څومره سرزوري دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_13.mp3', '', 1761754199, 1761754199),
(47460, 'Deuteronomy 9:14', 'Deuteronomy', 9, 14, 'پرېږده چې هغوی له منځه یوسم، ترڅو د هغوی نومونه د ځمکې د مخ څخه ورک شي. بیا به زه تا د یو داسې قوم پلار کړم چې د دوی څخه به لوی او قوي وي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_14.mp3', '', 1761754199, 1761754199),
(47461, 'Deuteronomy 9:15', 'Deuteronomy', 9, 15, 'نو زه بېرته د غره څخه راښکته شوم. په داسې حال کې چې د غره څخه د اور لمبې پورته کېدلې، ما د تیږو هغه دوه لوحې په خپلو لاسونو کې نیولې وې چې لوظ ورباندې لیکل شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_15.mp3', '', 1761754199, 1761754199),
(47462, 'Deuteronomy 9:16', 'Deuteronomy', 9, 16, 'ما ولیدل چې تاسو لا پخوا د خپل څښتن خدای د هغه امر څخه سرغړونه کړې وه چې هغه درکړی ؤ او د ځانونو دپاره مو د خوسي په شکل کې د طلایي بت په جوړولو سره د هغه په وړاندې ګناه کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_16.mp3', '', 1761754199, 1761754199),
(47463, 'Deuteronomy 9:17', 'Deuteronomy', 9, 17, 'نو هلته مې ستاسو په مخکې د تیږو هغه دوه لوحې وغورځولې او ټوټې ټوټې مې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_17.mp3', '', 1761754199, 1761754199),
(47464, 'Deuteronomy 9:18', 'Deuteronomy', 9, 18, 'نو زه یوځل بیا د څښتن په حضور کې څلوېښت شپې او ورځې پړمخې پرېوتم او خوراک او څښاک مې ونه کړ. ما دا کار د دې دپاره وکړ چې تاسو د څښتن په وړاندې ګناه کړې وه او هغه مو په قهر کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_18.mp3', '', 1761754199, 1761754199),
(47465, 'Deuteronomy 9:19', 'Deuteronomy', 9, 19, 'زه د څښتن د سخت قهر څخه ووېرېدم، ځکه چې هغه دومره ډېر په قهر ؤ چې تاسو تباه کړي، خو یوځل بیا یې زما دعا قبوله کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_19.mp3', '', 1761754199, 1761754199),
(47466, 'Deuteronomy 9:20', 'Deuteronomy', 9, 20, 'څښتن په هارون باندې دومره په قهر ؤ چې هغه ووژني، نو په هماغه وخت کې مې د هارون دپاره هم دعا وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_20.mp3', '', 1761754199, 1761754199),
(47467, 'Deuteronomy 9:21', 'Deuteronomy', 9, 21, 'ما هغه خوسی چې تاسو د سرو زرو څخه جوړ کړی ؤ او ستاسو د ګناه نتیجه وه راواخیست او اور ته مې واچاوه. بیا مې هغه ټوټې ټوټې کړ، په خاورو مې بدل کړ او هغه خاوره مې په هغې ویالې کې وغورځوله چې د غره څخه رابهېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_21.mp3', '', 1761754199, 1761754199),
(47468, 'Deuteronomy 9:22', 'Deuteronomy', 9, 22, 'کله چې تاسو په تبعیره، مسا او قبروت هتاوه کې وئ تاسو هلته هم خپل څښتن خدای په قهر کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_22.mp3', '', 1761754199, 1761754199),
(47469, 'Deuteronomy 9:23', 'Deuteronomy', 9, 23, 'بیا کله چې هغه تاسو د قادش برنیع څخه ولېږلئ او داسې حکم یې وکړ چې لاړ شئ او هغه خاوره ونیسئ چې څښتن تاسو ته درکړې ده، نو د هغه په وړاندې مو سرکښي وکړه. تاسو نه په هغه اعتبار وکړ او نه مو د هغه اطاعت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_23.mp3', '', 1761754199, 1761754199),
(47470, 'Deuteronomy 9:24', 'Deuteronomy', 9, 24, 'د هغه وخت راهیسې چې څښتن تاسو پېژندلي یئ، تاسو د هغه په وړاندې سرکښي کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_24.mp3', '', 1761754199, 1761754199),
(47471, 'Deuteronomy 9:25', 'Deuteronomy', 9, 25, 'نو زه د څښتن په حضور کې هغه څلوېښت شپې او ورځې پړمخې پرېوتم، ځکه زه پوهېدم چې هغه ستاسو د تباه کولو اراده لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_25.mp3', '', 1761754199, 1761754199),
(47472, 'Deuteronomy 9:26', 'Deuteronomy', 9, 26, 'او ما داسې دعا وکړه: ‹څښتن تعالی، خپل قوم یعنې هغه قوم چې تا په قوي مټ او ټول قدرت سره وژغوره او د مصر څخه دې راوویست، مه تباه کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_26.mp3', '', 1761754199, 1761754199),
(47473, 'Deuteronomy 9:27', 'Deuteronomy', 9, 27, 'خپل خدمتګاران یعنې ابراهیم، اسحاق او یعقوب در په یاد کړه او د دې قوم سرزورۍ، بدکارۍ او ګناه ته مه ګوره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_27.mp3', '', 1761754199, 1761754199),
(47474, 'Deuteronomy 9:28', 'Deuteronomy', 9, 28, 'که نه، نو مصریان به وایي چې تا نه شو کولای خپل قوم هغې ځمکې ته بوځې چې تا ورسره وعده کړې وه. هغوی به وایي چې تا د دې دپاره خپل قوم دښتې ته یووړ چې هغوی ووژنې، ځکه چې ته ورڅخه کرکه کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_28.mp3', '', 1761754199, 1761754199),
(47475, 'Deuteronomy 9:29', 'Deuteronomy', 9, 29, 'اخر دا هغه خلک دي چې تا د خپل قوم په توګه غوره کړل او په خپل قوي مټ او ټول قدرت سره دې د مصر څخه راوویستل.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy9_verse_29.mp3', '', 1761754199, 1761754199),
(47476, 'Judges 4:1', 'Judges', 4, 1, 'د ایهود د مړینې څخه وروسته د اسراییلو خلکو بیا داسې کارونه وکړل چې د څښتن په نظر کې بد وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_1.mp3', '', 1761754199, 1761754199),
(47477, 'Judges 4:2', 'Judges', 4, 2, 'نو څښتن هغوی یابین ته چې د کنعان یو پاچا ؤ او په حاصور کې یې پاچاهي کوله، په لاس ورکړل. د هغه د لښکر قوماندان سیسرا ؤ چې په حروشت حاجوییم کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_2.mp3', '', 1761754199, 1761754199),
(47478, 'Judges 4:3', 'Judges', 4, 3, 'یابین نهه سوه د اوسپنې جنګي ګاډۍ درلودلې او شل کاله یې په اسراییلو باندې سخت ظلم وکړ، نو اسراییلیانو د مرستې دپاره خدای ته فریاد وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_3.mp3', '', 1761754199, 1761754199),
(47479, 'Judges 4:4', 'Judges', 4, 4, 'په هغه وخت کې دبوره د لفیدوت ښځه پیغمبره وه او د قاضي په توګه یې د اسراییلو خدمت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_4.mp3', '', 1761754199, 1761754199),
(47480, 'Judges 4:5', 'Judges', 4, 5, 'هغه به د خرما د یوې ونې لاندې چې د دبورې په نوم یادېدله او د رامه او بیت ییل ترمنځ د افرایم په غرنۍ سیمه کې وه، کښېناستله. اسراییلیان به د خپلو دعوو د پرېکړې کولو په خاطر هغې ته راتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_5.mp3', '', 1761754199, 1761754199),
(47481, 'Judges 4:6', 'Judges', 4, 6, 'یوه ورځ هغې باراق د ابینوعم زوی چې د نفتالي په قادش کې اوسېده، راوغوښت او ورته ویې ویل: «د اسراییلو څښتن خدای په تا باندې امر کوي چې لاړ شې او د نفتالي او زبولون د قبیلو څخه لس زره کسان د ځان سره واخلې او د تابور غره ته یې بوځې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_6.mp3', '', 1761754199, 1761754199),
(47482, 'Judges 4:7', 'Judges', 4, 7, 'زه به د یابین د لښکر قوماندان سیسرا راولم چې د قیشون د سیند په غاړه ستاسو سره جګړه وکړي. د هغه سره به خپلې جنګي ګاډۍ او عسکر وي، خو زه به هغه تاته تسلیم کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_7.mp3', '', 1761754199, 1761754199),
(47483, 'Judges 4:8', 'Judges', 4, 8, 'بیا باراق هغې ته وویل: «که چېرې ته زما سره ځې، نو زه به لاړ شم او که چېرې ته راسره نه ځې، زه به هم لاړ نه شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_8.mp3', '', 1761754199, 1761754199),
(47484, 'Judges 4:9', 'Judges', 4, 9, 'دبورې وویل: «ډېر ښه، زه به ستا سره لاړه شم، خو دا یاد ساته چې که چېرې زه ستا سره لاړه شم او سیسرا مغلوب شي، نو ته به د دې بریالیتوب په خاطر هېڅ ویاړ تر لاسه نه کړې، ځکه چې څښتن به سیسرا یوې ښځې ته تسلیم کړي.» نو دبوره د باراق سره قادش ته لاړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_9.mp3', '', 1761754199, 1761754199),
(47485, 'Judges 4:10', 'Judges', 4, 10, 'باراق د زبولون او نفتالي د قبیلو خلک قادش ته راوغوښتل. لس زره کسان په هغه ځای کې سره راټول شول او باراق پسې روان شول. دبوره هم ورسره لاړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_10.mp3', '', 1761754199, 1761754199),
(47486, 'Judges 4:11', 'Judges', 4, 11, 'په هغه وخت کې حابر چې د قینیانو د طایفې څخه ؤ، ځان یې د نورو قینیانو څخه چې هغوی هم د حوباب د اولادې څخه وو، بېل کړی ؤ او خپله خېمه یې قادش ته نژدې په صعنایم کې د څېړۍ د ونې په څنګ کې ودرولې وه. حوباب د موسی د ښځې ورور ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_11.mp3', '', 1761754199, 1761754199),
(47487, 'Judges 4:12', 'Judges', 4, 12, 'کله چې سیسرا خبر شو چې باراق د تابور غره ته تللی دی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_12.mp3', '', 1761754199, 1761754199),
(47488, 'Judges 4:13', 'Judges', 4, 13, 'هغه خپلې ټولې نهه سوه جنګي ګاډۍ او خپل ټول کسان راوغوښتل او هغوی د حروشت حاجوییم څخه د قیشون د سیند خواته روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_13.mp3', '', 1761754199, 1761754199),
(47489, 'Judges 4:14', 'Judges', 4, 14, 'بیا دبورې باراق ته وویل: «لاړ شه! دا هغه ورځ ده چې څښتن به سیسرا تاته تسلیموي. څښتن ستاسو په مخکې روان دی.» نو باراق د خپلو لسو زرو کسانو سره د تابور د غره څخه راښکته شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_14.mp3', '', 1761754199, 1761754199),
(47490, 'Judges 4:15', 'Judges', 4, 15, 'کله چې باراق د خپل لښکر سره حمله وکړه، څښتن سیسرا د خپلو ټولو جنګي ګاډیو او کسانو سره وارخطا کړ. سیسرا د خپلې ګاډۍ څخه ښکته شو او وتښتېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_15.mp3', '', 1761754199, 1761754199),
(47491, 'Judges 4:16', 'Judges', 4, 16, 'باراق تر حروشت حاجوییم پورې د جنګي ګاډیو او لښکرو پسې شو او د سیسرا ټول لښکر ووژل شو. یو کس هم ژوندی پاتې نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_16.mp3', '', 1761754199, 1761754199),
(47492, 'Judges 4:17', 'Judges', 4, 17, 'سیسرا د یاعیل یعنې د قیني حابر د ښځې خېمې ته وروتښتېده، ځکه چې د حاصور د پاچا یابین او د قیني د طایفې ترمنځ دوستانه اړیکې موجودې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_17.mp3', '', 1761754199, 1761754199),
(47493, 'Judges 4:18', 'Judges', 4, 18, 'یاعیل د سیسرا هرکلي ته ورغله او ورته ویې ویل: «دننه راځه زما باداره، مه وېرېږه.» نو سیسرا د هغې خېمې ته ورننوت او یاعیل هغه په بړستن کې پټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_18.mp3', '', 1761754199, 1761754199),
(47494, 'Judges 4:19', 'Judges', 4, 19, 'سیسرا هغې ته وویل: «زه تږی یم ماته لږې اوبه راکړه.» هغې د شیدو ژی خلاص کړ او لږې شیدې یې ورته ورکړې او هغه یې بېرته پټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_19.mp3', '', 1761754199, 1761754199),
(47495, 'Judges 4:20', 'Judges', 4, 20, 'سیسرا هغې ته وویل: «د خېمې په دروازه کې ودرېږه، که چېرې څوک راشي او پوښتنه وکړي چې دلته څوک شته، ورته ووایه، نه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_20.mp3', '', 1761754199, 1761754199),
(47496, 'Judges 4:21', 'Judges', 4, 21, 'سیسرا ډېر ستړی شوی ؤ او په درانه خوب ویده شو. بیا د حابر ښځې یاعیل د خېمې یو موږی او څټک راواخیستل او غلې غلې سیسرا ته ورغله. هغې دا موږی د هغه په شقیقه باندې داسې ټک واهه چې سر یې په ځمکه کې ننوت او سیسرا مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_21.mp3', '', 1761754199, 1761754199),
(47497, 'Judges 4:22', 'Judges', 4, 22, 'کله چې باراق د سیسرا د لټولو دپاره راغی، نو یاعیل د هغه مخې ته ورغله او ویې ویل: «راځه چې هغه سړی دروښایم چې ته یې لټوې.» نو باراق د هغې سره خېمې ته ننوت او هلته سیسرا په داسې حال کې چې موږی یې په سر کې ننوتی ؤ، مړ پروت ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_22.mp3', '', 1761754199, 1761754199),
(47498, 'Judges 4:23', 'Judges', 4, 23, 'نو په هغه ورځ خدای اسراییلیانو ته د کنعان په پاچا یابین باندې بری ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_23.mp3', '', 1761754199, 1761754199),
(47499, 'Judges 4:24', 'Judges', 4, 24, 'له هغې ورځې څخه وروسته اسراییلیان د یابین په وړاندې قوي کېدل، ترڅو چې هغه یې له منځه یووړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges4_verse_24.mp3', '', 1761754199, 1761754199),
(47500, 'Exodus 12:1', 'Exodus', 12, 1, 'څښتن په مصر کې موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_1.mp3', '', 1761754199, 1761754199),
(47501, 'Exodus 12:2', 'Exodus', 12, 2, '«له دې وروسته به دا میاشت ستاسو دپاره د کال لومړۍ میاشت وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_2.mp3', '', 1761754199, 1761754199),
(47502, 'Exodus 12:3', 'Exodus', 12, 3, 'د اسراییلو ټول قوم ته دا لارښوونې وکړې چې د دې میاشتې په لسمه ورځ باید هر سړی د خپلې کورنۍ دپاره یو یو وری یا سېرلی واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_3.mp3', '', 1761754199, 1761754199),
(47503, 'Exodus 12:4', 'Exodus', 12, 4, 'که چېرې یوه کورنۍ دومره کوچنۍ وي چې ټول حیوان نه شي خوړلی، نو د خپل نژدې ګاونډي سره دې هغه ووېشي او د خلکو شمېر دې په نظر کې ونیسي. د هر کس دپاره دې دومره وټاکل شي څومره چې خوړلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_4.mp3', '', 1761754199, 1761754199),
(47504, 'Exodus 12:5', 'Exodus', 12, 5, 'تاسو کولای شئ چې پسه او یا سېرلی غوره کړئ. خو هغه باید یو کلن وي او نر وي او کوم عیب هم ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_5.mp3', '', 1761754199, 1761754199),
(47505, 'Exodus 12:6', 'Exodus', 12, 6, 'تاسو باید د دې میاشتې تر څوارلسمې ورځې پورې هغه وساتئ، بیا به ټول قوم هغه په ماښام کې حلال کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_6.mp3', '', 1761754199, 1761754199),
(47506, 'Exodus 12:7', 'Exodus', 12, 7, 'خلک دې لږه وینه واخلي خپلو کورونو د دروازو د چوکاټ په دواړو خواو او پورتنۍ برخې باندې یې چې د دې حیواناتو غوښه په کې خوړل کیږي، وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_7.mp3', '', 1761754199, 1761754199),
(47507, 'Exodus 12:8', 'Exodus', 12, 8, 'په هماغه شپه دې هغوی غوښه په اور باندې کباب کړي او د ترخو بوټو او فطیرې ډوډۍ سره دې وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_8.mp3', '', 1761754199, 1761754199),
(47508, 'Exodus 12:9', 'Exodus', 12, 9, 'تاسو هغه غوښه خامه او یا خوټول شوې مه خورئ. هغه د سر، پښو او د نس د دنننیو برخو سره په اور باندې کباب کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_9.mp3', '', 1761754199, 1761754199),
(47509, 'Exodus 12:10', 'Exodus', 12, 10, 'د هغې غوښې څخه تر سهار پورې لږه هم مه پرېږدئ. که چېرې لږه ورڅخه پاتې شي، نو هغه وسوځوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_10.mp3', '', 1761754199, 1761754199),
(47510, 'Exodus 12:11', 'Exodus', 12, 11, 'تاسو به هغه زر زر خورئ، ځکه چې د سفر دپاره به ملا تړئ. خپلې څپلۍ به په پښو کړئ او امساګانې به مو په لاسونو کې ونیسئ. دا د فسحې اختر دی چې زما یعنې څښتن د درناوي په خاطر لمانځل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus12_verse_11.mp3', '', 1761754199, 1761754199);